class FamilyActivityScheduler:
    def __init__(self):
        self.activities = {}

    def add_activity(self):
        name = input("Enter the name of the activity: ")
        date = input("Enter the date of the activity (YYYY-MM-DD): ")
        time = input("Enter the time of the activity (HH:MM): ")
        description = input("Enter a brief description of the activity: ")

        if date in self.activities:
            print("Activity for this date already exists. Please choose a different date.")
        else:
            self.activities[date] = {
                "name": name,
                "time": time,
                "description": description
            }
            print(f"Activity '{name}' added successfully.")

    def view_activities(self):
        if not self.activities:
            print("No activities scheduled.")
        else:
            for date, activity in self.activities.items():
                print(f"Date: {date}")
                print(f"Name: {activity['name']}")
                print(f"Time: {activity['time']}")
                print(f"Description: {activity['description']}\n")

    def delete_activity(self):
        date = input("Enter the date of the activity you want to delete (YYYY-MM-DD): ")
        if date in self.activities:
            del self.activities[date]
            print(f"Activity for {date} deleted successfully.")
        else:
            print("No activity found for this date.")

    def run(self):
        while True:
            print("\nFamily Activity Scheduler")
            print("1. Add Activity")
            print("2. View Activities")
            print("3. Delete Activity")
            print("4. Exit")
            choice = input("Choose an option: ")

            if choice == "1":
                self.add_activity()
            elif choice == "2":
                self.view_activities()
            elif choice == "3":
                self.delete_activity()
            elif choice == "4":
                print("Goodbye!")
                break
            else:
                print("Invalid option. Please choose a valid option.")

if __name__ == "__main__":
    scheduler = FamilyActivityScheduler()
    scheduler.run()
